47	// Translates a DSLX expression tree into a linear sequence of bytecodes.
48	class BytecodeEmitter : public ExprVisitor {
49	 public:
50	  // `caller_bindings` contains the symbolic bindings associated with the
51	  // _caller_ of `f`, if any, and is used to determine the symbolic bindings for
52	  // `f` itself. It will be std::nullopt for non-parametric functions.
53	  static absl::StatusOr<std::unique_ptr<BytecodeFunction>> Emit(
54	      ImportData* import_data, const TypeInfo* type_info, const Function& f,
55	      const std::optional<ParametricEnv>& caller_bindings,
56	      const BytecodeEmitterOptions& options = BytecodeEmitterOptions());
57	
58	  // TODO(rspringer): 2022-03-16: I think we can delete `caller_bindings`.
59	  static absl::StatusOr<std::unique_ptr<BytecodeFunction>> EmitExpression(
60	      ImportData* import_data, const TypeInfo* type_info, const Expr* expr,
61	      const absl::flat_hash_map<std::string, InterpValue>& env,
62	      const std::optional<ParametricEnv>& caller_bindings,
63	      const BytecodeEmitterOptions& options = BytecodeEmitterOptions());
64	
65	  static absl::StatusOr<std::unique_ptr<BytecodeFunction>> EmitProcConfig(
66	      ImportData* import_data, const TypeInfo* type_info, const Function& f,
67	      const std::optional<ParametricEnv>& caller_bindings,
68	      std::optional<absl::FunctionRef<int64_t()>> channel_instance_allocator =
69	          std::nullopt,
70	      const BytecodeEmitterOptions& options = BytecodeEmitterOptions());
71	
72	  // Emits a function, just as the above, but reserves the first N slots for
73	  // the given proc members.
74	  static absl::StatusOr<std::unique_ptr<BytecodeFunction>> EmitProcNext(
75	      ImportData* import_data, const TypeInfo* type_info, const Function& f,
76	      const std::optional<ParametricEnv>& caller_bindings,
77	      const std::vector<NameDef*>& legacy_proc_members,
78	      const BytecodeEmitterOptions& options = BytecodeEmitterOptions());
79	
80	 private:
81	  BytecodeEmitter(
82	      ImportData* import_data, const TypeInfo* type_info,
83	      const std::optional<ParametricEnv>& caller_bindings,
84	      std::optional<absl::FunctionRef<int64_t()>> channel_instance_allocator,
85	      const BytecodeEmitterOptions& options);
86	  ~BytecodeEmitter() override;
87	
88	  static absl::StatusOr<std::unique_ptr<BytecodeFunction>> EmitInternal(
89	      ImportData* import_data, const TypeInfo* type_info, const Function& f,
90	      const std::optional<ParametricEnv>& caller_bindings,
91	      const std::vector<NameDef*>& legacy_proc_members,
92	      std::optional<absl::FunctionRef<int64_t()>> channel_instance_allocator,
93	      const BytecodeEmitterOptions& options = BytecodeEmitterOptions());
94	
95	  static void LogEmittedFunction(const Function& f, const TypeInfo* ti,
96	                                 const std::vector<Bytecode>& content);
97	
98	  // Initializes namedef-to-slot mapping.
99	  absl::Status Init(const Function& f);
100	
101	  // Precondition: node must be Bits typed.
102	  absl::StatusOr<bool> IsBitsTypeNodeSigned(const AstNode* node) const;
