#ifndef XLS_DSLX_BYTECODE_BYTECODE_EMITTER_H_
#define XLS_DSLX_BYTECODE_BYTECODE_EMITTER_H_

#include <cstdint>
#include <memory>
#include <optional>
#include <string>
#include <utility>
