142	// A FIFO which backs channel instances in the bytecode interpreter.
143	class InterpValueChannel {
144	 public:
145	  InterpValueChannel(int64_t id) : id_(id) {}
146	  InterpValueChannel(const InterpValueChannel&) = delete;
147	  InterpValueChannel(InterpValueChannel&&) = default;
148	
149	  int64_t GetId() const { return id_; }
150	  bool IsEmpty() const { return queue_.empty(); }
151	  int64_t GetSize() const { return queue_.size(); }
152	  InterpValue Read() {
153	    InterpValue result = std::move(queue_.front());
154	    queue_.pop_front();
155	    return result;
156	  }
157	  void Write(InterpValue v) { queue_.push_back(std::move(v)); }
158	
159	 private:
160	  const int64_t id_;
161	  std::deque<InterpValue> queue_;
162	};
