220	      int64_t channel_id, const AstNode* definer) override {
221	    VLOG(5) << "Allocating channel ID " << channel_id
222	            << " from definer: " << definer->ToString();
223	    XLS_RET_CHECK(definer->kind() == AstNodeKind::kParam ||
224	                  definer->kind() == AstNodeKind::kChannelDecl);
225	    auto& value = channels_[channel_id];
226	    if (value == nullptr) {
227	      value = std::make_unique<InterpValueChannel>(channel_id);
228	      definers_[channel_id] = definer;
229	    } else if (definers_.at(channel_id) != definer) {
230	      return absl::AlreadyExistsError(absl::StrCat(
231	          "There is already a channel allocated to ID: ", channel_id));
232	    }
233	    return value.get();
234	  }
235	
236	  // When a ProcDef constructor forwards a channel to another ProcDef
237	  // constructor, this function should be used to associate the original channel
238	  // ID with the Param that is the definer of the forwarded ChannelReference.
239	  void Forward(int64_t channel_id, const TypeInfo* ti, const Param* param) {
240	    InterpValueChannel* channel = channels_.at(channel_id).get();
241	    forwarded_channels_.insert_or_assign(std::make_pair(ti, param), channel);
242	  }
243	
244	  InterpValueChannel& GetChannel(
245	      const TypeInfo* ti,
246	      const InterpValue::ChannelReference& channel_ref) override {
247	    CHECK(channel_ref.GetChannelId().has_value());
248	    const auto it_by_id = channels_.find(*channel_ref.GetChannelId());
249	    if (it_by_id != channels_.end()) {
250	      return *it_by_id->second;
251	    }
252	
253	    CHECK(channel_ref.GetDefiner().has_value());
254	    return *forwarded_channels_.at(
255	        std::make_pair(ti, *channel_ref.GetDefiner()));
256	  }
257	
258	 private:
259	  absl::flat_hash_map<int64_t, const AstNode*> definers_;
260	  absl::flat_hash_map<std::pair<const TypeInfo*, const AstNode*>,
261	                      InterpValueChannel*>
262	      forwarded_channels_;
263	};
