323	absl::Status BytecodeInterpreter::InitFrame(BytecodeFunction* bf,
324	                                            absl::Span<const InterpValue> args,
325	                                            const TypeInfo* type_info) {
326	  XLS_RET_CHECK(frames_.empty());
327	
328	  // In "mission mode" we expect type_info to be non-null in the frame, but for
329	  // bytecode-level testing we may not have an AST.
330	  if (type_info == nullptr && bf->owner() != nullptr) {
331	    type_info = import_data_->GetRootTypeInfo().value();
332	  }
333	  frames_.push_back(Frame(bf,
334	                          std::vector<InterpValue>(args.begin(), args.end()),
335	                          type_info, std::nullopt, /*initial_args=*/{}));
336	  return absl::OkStatus();
337	}
338	
339	/* static */ absl::StatusOr<std::unique_ptr<BytecodeInterpreter>>
340	BytecodeInterpreter::CreateUnique(
341	    ImportData* import_data, const std::optional<ProcId>& proc_id,
342	    BytecodeFunction* bf, const std::vector<InterpValue>& args,
343	    std::optional<InterpValueChannelManager*> channel_manager,
344	    const BytecodeInterpreterOptions& options,
345	    std::optional<DslxInterpreterEvents*> events) {
346	  auto interp = absl::WrapUnique(new BytecodeInterpreter(
347	      import_data, proc_id, channel_manager, options, events));
348	  XLS_RETURN_IF_ERROR(interp->InitFrame(bf, args, bf->type_info()));
349	  return interp;
350	}
351	
352	absl::Status BytecodeInterpreter::Run(bool* progress_made) {
353	  blocked_channel_info_ = std::nullopt;
354	  while (!frames_.empty()) {
355	    Frame* frame = &frames_.back();
356	    while (frame->pc() < frame->bf()->bytecodes().size()) {
357	      const std::vector<Bytecode>& bytecodes = frame->bf()->bytecodes();
358	      const Bytecode& bytecode = bytecodes.at(frame->pc());
359	      VLOG(2) << "Bytecode: " << bytecode.ToString(file_table());
360	      if (proc_id_.has_value()) {
361	        VLOG(2) << "Proc: " << proc_id_->ToString();
362	      }
363	      VLOG(2) << std::hex << "PC: " << frame->pc() << " : "
364	              << bytecode.ToString(file_table());
365	      VLOG(3) << absl::StreamFormat(" - stack depth %d [%s]", stack_.size(),
366	                                    stack_.ToString());
367	      int64_t old_pc = frame->pc();
368	      XLS_RETURN_IF_ERROR(EvalNextInstruction());
369	      VLOG(3) << absl::StreamFormat(" - stack depth %d [%s]", stack_.size(),
370	                                    stack_.ToString());
371	
372	      if (bytecode.op() == Bytecode::Op::kCall) {
373	        frame = &frames_.back();
374	      } else if (frame->pc() != old_pc + 1) {
375	        XLS_RET_CHECK(bytecodes.at(frame->pc()).op() == Bytecode::Op::kJumpDest)
376	            << "Jumping from PC " << old_pc << " to PC: " << frame->pc()
377	            << " bytecode: " << bytecodes.at(frame->pc()).ToString(file_table())
378	            << " not a jump_dest or old bytecode: "
379	            << bytecode.ToString(file_table()) << " was not a call op.";
380	      }
381	      if (progress_made != nullptr) {
382	        *progress_made = true;
383	      }
384	    }
385	
386	    // Run the post-fn eval hook, if our function has a return value and if we
387	    // actually have a hook.
388	    const Function* source_fn = frame->bf()->source_fn();
389	    if (source_fn != nullptr) {
390	      std::optional<Type*> fn_return = frame->type_info()->GetItem(source_fn);
391	      if (fn_return.has_value()) {
392	        bool fn_returns_value = *fn_return.value() != *Type::MakeUnit();
393	        if (options_.post_fn_eval_hook() != nullptr && fn_returns_value) {
394	          ParametricEnv holder;
395	          const ParametricEnv* bindings = &holder;
396	          if (frame->bindings().has_value()) {
397	            bindings = &frame->bindings().value();
398	          }
399	          XLS_RETURN_IF_ERROR(options_.post_fn_eval_hook()(
400	              source_fn, frame->initial_args(), bindings, stack_.PeekOrDie()));
401	        }
402	      }
403	    }
404	
405	    // Emit a call-return trace message at function exit.
406	    if (options_.trace_calls() && events_.has_value() && source_fn != nullptr) {
407	      int64_t call_depth = static_cast<int64_t>(frames_.size()) - 1;
408	      const InterpValue& ret = stack_.PeekOrDie();
409	      (*events_)->AddTraceCallReturnMessage(import_data_->file_table(),
410	                                            source_fn->span(),
411	                                            source_fn->identifier(), call_depth,
412	                                            options_.format_preference(), ret);
413	    }
414	
415	    // We've reached the end of a function. Time to load the next frame up!
416	    frames_.pop_back();
417	  }
418	
419	  return absl::OkStatus();
420	}
421	
422	absl::StatusOr<std::vector<InterpValue>>
423	BytecodeInterpreter::PopArgsRightToLeft(size_t count) {
424	  std::vector<InterpValue> args(count, InterpValue::MakeToken());
425	  for (int i = 0; i < count; i++) {
426	    XLS_ASSIGN_OR_RETURN(InterpValue arg, Pop());
427	    args[count - i - 1] = arg;
428	  }
429	  return args;
430	}
431	
432	absl::Status BytecodeInterpreter::EvalNextInstruction() {
433	  Frame* frame = &frames_.back();
434	  const std::vector<Bytecode>& bytecodes = frame->bf()->bytecodes();
435	  if (frame->pc() >= bytecodes.size()) {
436	    return absl::InvalidArgumentError(
437	        absl::StrFormat("Frame PC exceeds bytecode length: %d vs %d.",
438	                        frame->pc(), bytecodes.size()));
439	  }
440	  const Bytecode& bytecode = bytecodes.at(frame->pc());
441	  VLOG(10) << "Running bytecode: " << bytecode.ToString(file_table())
442	           << " depth before: " << stack_.size();
443	  switch (bytecode.op()) {
444	    case Bytecode::Op::kUAdd: {
445	      XLS_RETURN_IF_ERROR(EvalAdd(bytecode, /*is_signed=*/false));
446	      break;
447	    }
448	    case Bytecode::Op::kSAdd: {
449	      XLS_RETURN_IF_ERROR(EvalAdd(bytecode, /*is_signed=*/true));
450	      break;
451	    }
452	    case Bytecode::Op::kAnd: {
453	      XLS_RETURN_IF_ERROR(EvalAnd(bytecode));
454	      break;
455	    }
456	    case Bytecode::Op::kCall: {
457	      XLS_RETURN_IF_ERROR(EvalCall(bytecode));
458	      return absl::OkStatus();
459	    }
460	    case Bytecode::Op::kCast: {
461	      XLS_RETURN_IF_ERROR(EvalCast(bytecode));
462	      break;
463	    }
464	    case Bytecode::Op::kCheckedCast: {
465	      XLS_RETURN_IF_ERROR(EvalCast(bytecode, /*is_checked=*/true));
466	      break;
467	    }
468	    case Bytecode::Op::kConcat: {
469	      XLS_RETURN_IF_ERROR(EvalConcat(bytecode));
470	      break;
471	    }
472	    case Bytecode::Op::kCreateArray: {
473	      XLS_RETURN_IF_ERROR(EvalCreateArray(bytecode));
